@Appender(
    _apply_docs["template"].format(
        input="dataframe", examples=_apply_docs["dataframe_examples"]
    )
)
def apply(self, func, *args, include_groups: bool = True, **kwargs) -> NDFrameT:
    orig_func = func
    func = com.is_builtin_func(func)
    if orig_func != func:
        alias = com._builtin_table_alias[orig_func]
        warn_alias_replacement(self, orig_func, alias)

    if isinstance(func, str):
        if hasattr(self, func):
            res = getattr(self, func)
            if callable(res):
                return res(*args, **kwargs)
            elif args or kwargs:
                raise ValueError(f"Cannot pass arguments to property {func}")
            return res

        else:
            raise TypeError(f"apply func should be callable, not '{func}'")

    elif args or kwargs:
        if callable(func):

            @wraps(func)
            def f(g):
                return func(g, *args, **kwargs)

        else:
            raise ValueError(
                "func must be a callable if args or kwargs are supplied"
            )
    else:
        f = func

    if not include_groups:
        return self._python_apply_general(f, self._obj_with_exclusions)

    # ignore SettingWithCopy here in case the user mutates
    with option_context("mode.chained_assignment", None):
        try:
            result = self._python_apply_general(f, self._selected_obj)
            if (
                not isinstance(self.obj, Series)
                and self._selection is None
                and self._selected_obj.shape != self._obj_with_exclusions.shape
            ):
                warnings.warn(
                    message=_apply_groupings_depr.format(
                        type(self).__name__, "apply"
                    ),
                    category=FutureWarning,
                    stacklevel=find_stack_level(),
                )
        except TypeError:
            # gh-20949
            # try again, with .apply acting as a filtering
            # operation, by excluding the grouping column
            # This would normally not be triggered
            # except if the udf is trying an operation that
            # fails on *some* columns, e.g. a numeric operation
            # on a string grouper column

            return self._python_apply_general(f, self._obj_with_exclusions)

    return result

@final
def _python_apply_general(
    self,
    f: Callable,
    data: DataFrame | Series,
    not_indexed_same: bool | None = None,
    is_transform: bool = False,
    is_agg: bool = False,
) -> NDFrameT:
    """
    Apply function f in python space

    Parameters
    ----------
    f : callable
        Function to apply
    data : Series or DataFrame
        Data to apply f to
    not_indexed_same: bool, optional
        When specified, overrides the value of not_indexed_same. Apply behaves
        differently when the result index is equal to the input index, but
        this can be coincidental leading to value-dependent behavior.
    is_transform : bool, default False
        Indicator for whether the function is actually a transform
        and should not have group keys prepended.
    is_agg : bool, default False
        Indicator for whether the function is an aggregation. When the
        result is empty, we don't want to warn for this case.
        See _GroupBy._python_agg_general.

    Returns
    -------
    Series or DataFrame
        data after applying f
    """
    values, mutated = self._grouper.apply_groupwise(f, data, self.axis)
    if not_indexed_same is None:
        not_indexed_same = mutated

    return self._wrap_applied_output(
        data,
        values,
        not_indexed_same,
        is_transform,
    )

@final
def _agg_general(
    self,
    numeric_only: bool = False,

