"""Definition of the interface every parallelized pandas operation implements."""

from abc import ABC, abstractmethod
from typing import Any, Callable, Dict, Iterable, Iterator, List

from ..progress_bars import ProgressBarsType, progress_wrapper


class DataType(ABC):
    """How to split, compute and merge back one kind of pandas operation.

    A `DataType` is only a namespace of static methods: instances are never
    created, which makes it trivially serializable (only `work` is sent to the
    workers).
    """

    @staticmethod
    @abstractmethod
    def get_chunks(nb_workers: int, data: Any, **kwargs) -> Iterator[Any]:
        """Split `data` into at most `nb_workers` chunks (executed by the master)."""

    @staticmethod
    def get_nb_items(chunk: Any, **kwargs) -> int:
        """Number of times the user defined function is called for this chunk.

        Only used to display progress bars.
        """
        try:
            return len(chunk)
        except TypeError:  # pragma: no cover - defensive
            return 0

    @staticmethod
    def get_work_extra(data: Any) -> Dict[str, Any]:
        """Additional (picklable) information needed by the workers."""
        return dict()

    @staticmethod
    @abstractmethod
    def work(
        data: Any,
        user_defined_function: Callable,
        user_defined_function_args: tuple,
        user_defined_function_kwargs: Dict[str, Any],
        extra: Dict[str, Any],
    ) -> Any:
        """Compute the result of one chunk (executed by a worker)."""

    @staticmethod
    def get_reduce_extra(data: Any, user_defined_function_kwargs: Dict[str, Any]) -> Dict[str, Any]:
        """Additional information needed to merge the results back together."""
        return dict()

    @staticmethod
    @abstractmethod
    def reduce(datas: Iterable[Any], extra: Dict[str, Any]) -> Any:
        """Merge the results of every worker (executed by the master)."""


def wrap_user_defined_function_in_work(
    user_defined_function: Callable, nb_items: int, extra: Dict[str, Any]
) -> Callable:
    """Add progress bar monitoring to a user defined function called by `work`.

    Data types whose progress bar type is `InWorkFunction` are responsible for
    counting the items they process themselves, because one item is not one call
    to the user defined function (a group, a window, ...).
    """
    if extra.get("progress_bars_type") != ProgressBarsType.InWorkFunction:
        return user_defined_function

    return progress_wrapper(
        user_defined_function,
        extra["master_workers_queue"],
        extra["worker_index"],
        nb_items,
    )


def progress_counter(nb_items: int, extra: Dict[str, Any]) -> Callable[[], None]:
    """Return a callable to be called each time an item has been processed."""
    counter = wrap_user_defined_function_in_work(lambda: None, nb_items, extra)

    return counter


def concat_or_empty(datas: List[Any], empty_like: Any = None):
    """`pandas.concat`, tolerant to an empty list of results."""
    import pandas as pd

    datas = [data for data in datas if data is not None]

    if not datas:
        if empty_like is None:
            return pd.DataFrame()
        return empty_like

    return pd.concat(datas, copy=False)

