from typing import Any, Callable, Dict, Iterable, Iterator, List

import pandas as pd

from ..utils import chunk
from .generic import DataType


def get_axis_int(data: pd.DataFrame, args: tuple, kwargs: Dict[str, Any]) -> int:
    """Return the axis (as an integer) `DataFrame.apply` will be called with.

    `axis` is the first optional positional argument of `DataFrame.apply`, and can
    also be given as a keyword argument. An invalid axis raises the very same
    `ValueError` as `pandas` would.
    """
    if "axis" in kwargs:
        axis = kwargs["axis"]
    elif args:
        axis = args[0]
    else:
        axis = 0

    # Raises `ValueError: No axis named ... for object type DataFrame`
    return data._get_axis_number(axis)


class DataFrame:
    class Apply(DataType):
        @staticmethod
        def get_chunks(
            nb_workers: int, data: pd.DataFrame, **kwargs
        ) -> Iterator[pd.DataFrame]:
            axis_int = get_axis_int(
                data,
                kwargs.get("user_defined_function_args", ()),
                kwargs.get("user_defined_function_kwargs", {}),
            )

            # `apply` along the rows (axis=1) means the data is split by rows, and
            # `apply` along the columns (axis=0) that it is split by columns.
            opposite_axis_int = 1 - axis_int

            for chunk_ in chunk(data.shape[opposite_axis_int], nb_workers):
                yield data.iloc[chunk_] if axis_int == 1 else data.iloc[:, chunk_]

        @staticmethod
        def get_nb_items(chunk: pd.DataFrame, **kwargs) -> int:
            axis_int = get_axis_int(
                chunk,
                kwargs.get("user_defined_function_args", ()),
                kwargs.get("user_defined_function_kwargs", {}),
            )

            return chunk.shape[1 - axis_int]

        @staticmethod
        def work(
            data: pd.DataFrame,
            user_defined_function: Callable,
            user_defined_function_args: tuple,
            user_defined_function_kwargs: Dict[str, Any],
            extra: Dict[str, Any],
        ) -> Any:
            return data.apply(
                user_defined_function,
                *user_defined_function_args,
                **user_defined_function_kwargs,
            )

        @staticmethod
        def get_reduce_extra(
            data: pd.DataFrame, user_defined_function_kwargs: Dict[str, Any]
        ) -> Dict[str, Any]:
            return {"axis": user_defined_function_kwargs.get("axis", 0)}

        @staticmethod
        def reduce(datas: Iterable[Any], extra: Dict[str, Any]) -> Any:
            datas: List[Any] = list(datas)

            if len(datas) == 1:
                return datas[0]

            if all(isinstance(data, pd.Series) for data in datas):
                # The user defined function reduced each row/column to a scalar.
                return pd.concat(datas, copy=False)

            axis = 0 if extra["axis"] in (1, "columns") else 1

            return pd.concat(datas, copy=False, axis=axis)

