                yield data.iloc[chunk_]

        @staticmethod
        def get_nb_items(chunk: pd.DataFrame, **kwargs) -> int:
            # The user defined function is called once per cell.
            return chunk.shape[0] * chunk.shape[1]

        @staticmethod
        def work(
            data: pd.DataFrame,
            user_defined_function: Callable,
            user_defined_function_args: tuple,
            user_defined_function_kwargs: Dict[str, Any],
            extra: Dict[str, Any],
