                *user_defined_function_args,
                **user_defined_function_kwargs,
            )

        @staticmethod
        def reduce(datas: Iterable[Any], extra: Dict[str, Any]) -> pd.DataFrame:
            datas = list(datas)

            if len(datas) == 1:
                return datas[0]

            return pd.concat(datas, copy=False)

