"""Parallelization of `DataFrameGroupBy.apply` (and `SeriesGroupBy.apply`)."""

import inspect
from typing import Any, Callable, Dict, Iterable, Iterator, List, Tuple

import pandas as pd

from ..utils import chunk, df_indexed_like, get_pandas_version
from .generic import DataType, wrap_user_defined_function_in_work


def get_grouper(data: Any) -> Any:
    """Return the `BaseGrouper` of a `GroupBy` object.

    `GroupBy.grouper` has been renamed `GroupBy._grouper` in pandas 2.2 (the
    public attribute being deprecated).
    """
    grouper = getattr(data, "_grouper", None)

    return grouper if grouper is not None else data.grouper


def get_axis_int(data: Any) -> int:
    """Return the axis the `GroupBy` object works on (always 0 since pandas 2.1)."""
    return getattr(data, "axis", 0) or 0


def get_apply_object(data: Any) -> Any:
    """Return the object `GroupBy.apply` splits into groups.

    Up to pandas 2.x, the grouping columns are part of the groups given to the
    user defined function (`include_groups=True`). This is not the case anymore
    starting with pandas 3.0.
    """
    if get_pandas_version() >= (3, 0):
        return data._obj_with_exclusions

    return data._selected_obj


def iter_groups(data: Any) -> Iterator[Tuple[Any, Any]]:
    """Iterate over the `(key, group)` pairs of a `GroupBy` object.

    The very same pandas internals as `GroupBy.apply` are used, so the keys given
    to the user defined function through `group.name` are identical to the ones
    pandas would have used.
    """
    grouper = get_grouper(data)
    apply_object = get_apply_object(data)

    try:
        return grouper.get_iterator(apply_object, axis=get_axis_int(data))
    except TypeError:
        # The `axis` parameter has been removed in pandas 3.0.
        return grouper.get_iterator(apply_object)


def wrap_applied_output(data: Any, values: List[Any], not_indexed_same: bool) -> Any:
    """Build the result of a `groupby.apply` from the results of each group.

    This delegates the (quite involved) work of guessing the shape of the result
    to pandas itself, which guarantees `parallel_apply` and `apply` return exactly
    the same thing.
    """
    wrapper = data._wrap_applied_output
    parameters = inspect.signature(wrapper).parameters

    if "is_transform" in parameters:
        # pandas >= 1.5
        return wrapper(get_apply_object(data), values, not_indexed_same, False)

    if "data" in parameters:
        # pandas >= 1.3
        return wrapper(get_apply_object(data), values, not_indexed_same)

    # pandas < 1.3: the keys were given instead of the data.
    keys = list(get_grouper(data).group_keys_seq)

    return wrapper(keys, values, not_indexed_same)


class GroupByApply(DataType):
    """Apply a user defined function to each group, in parallel.

    Chunks are lists of `(key, group)` pairs: groups are dispatched to the
    workers, and the results are given back to pandas, in the original order, to
    be assembled.
    """

    @staticmethod
    def get_chunks(nb_workers: int, data: Any, **kwargs) -> Iterator[List[Tuple[Any, Any]]]:
        iterator = iter_groups(data)

        for chunk_ in chunk(get_grouper(data).ngroups, nb_workers):
            yield [next(iterator) for _ in range(chunk_.stop - chunk_.start)]

    @staticmethod
    def get_work_extra(data: Any) -> Dict[str, Any]:
        return {"axis": get_axis_int(data)}

    @staticmethod
    def work(
        data: List[Tuple[Any, Any]],
        user_defined_function: Callable,
        user_defined_function_args: tuple,
        user_defined_function_kwargs: Dict[str, Any],
        extra: Dict[str, Any],
    ) -> Tuple[List[Any], bool]:
        axis = extra.get("axis", 0)
        user_defined_function = wrap_user_defined_function_in_work(
            user_defined_function, len(data), extra
        )

        results = []
        mutated = False

        for key, group in data:
            # Some user defined functions rely on `group.name`, exactly like
            # `pandas.core.groupby.ops.BaseGrouper.apply_groupwise` does.
            object.__setattr__(group, "name", key)
            group_axes = group.axes

            result = user_defined_function(
                group, *user_defined_function_args, **user_defined_function_kwargs
            )

            if not mutated and not df_indexed_like(result, group_axes, axis):
                mutated = True

            results.append(result)

        return results, mutated

    @staticmethod
    def get_reduce_extra(
        data: Any, user_defined_function_kwargs: Dict[str, Any]
    ) -> Dict[str, Any]:
        return {"groupby": data}

    @staticmethod
    def reduce(datas: Iterable[Tuple[List[Any], bool]], extra: Dict[str, Any]) -> Any:
        values: List[Any] = []
        mutated = False

        for results, chunk_mutated in datas:
            values.extend(results)
            mutated = mutated or chunk_mutated

        return wrap_applied_output(extra["groupby"], values, mutated)


class DataFrameGroupBy:
    class Apply(GroupByApply):
        pass

