"""Parallelization of `Rolling.apply` and `Expanding.apply` (without `groupby`)."""

from typing import Any, Callable, Dict, Iterable, Iterator, Tuple

import pandas as pd
from pandas.core.window.expanding import Expanding

from ..utils import chunk_with_prepended_items
from .generic import DataType, wrap_user_defined_function_in_work

# Attributes of a window object which are not parameters of `obj.rolling(...)` or
# `obj.expanding(...)`.
NOT_WINDOW_PARAMETERS = ("_grouper", "_as_index")


def get_window_kind(data: Any) -> str:
    """Return either `"rolling"` or `"expanding"`."""
    return "expanding" if isinstance(data, Expanding) else "rolling"


def get_window_attrs(data: Any) -> Dict[str, Any]:
    """Return the keyword arguments needed to rebuild a similar window object."""
    attrs = {
        attr: getattr(data, attr)
        for attr in data._attributes
        if attr not in NOT_WINDOW_PARAMETERS
    }

    # `axis` is deprecated since pandas 2.1 and only kept when explicitly used.
    if attrs.get("axis", 0) in (0, None):
        attrs.pop("axis", None)

    return attrs


def build_window(data: Any, window_kind: str, attrs: Dict[str, Any]) -> Any:
    """Rebuild a window object (`rolling` or `expanding`) on top of `data`."""
    return getattr(data, window_kind)(**attrs)


def get_selected_object(data: Any) -> Any:
    """Return the `Series`/`DataFrame` the window object works on."""
    selected_obj = getattr(data, "_selected_obj", None)

    return data.obj if selected_obj is None else selected_obj


class SeriesRolling:
    class Apply(DataType):
        @staticmethod
        def get_chunks(
            nb_workers: int, data: Any, **kwargs
        ) -> Iterator[Tuple[int, Any]]:
            obj = get_selected_object(data)
            nb_items = obj.shape[0]
            start_offset, nb_chunks = SeriesRolling.Apply.get_start_offset_and_nb_chunks(
                data, nb_items, nb_workers
            )

            for slice_, nb_prepended in chunk_with_prepended_items(
                nb_items, nb_chunks, start_offset
            ):
                yield nb_prepended, obj.iloc[slice_]

        @staticmethod
        def get_start_offset_and_nb_chunks(
            data: Any, nb_items: int, nb_workers: int
        ) -> Tuple[int, int]:
            """Number of items to prepend to each chunk, and number of chunks.

            A window needs the items which precede it to be computed, so chunks
            have to overlap. When the size of this overlap cannot be determined
            (time based window, custom indexer, centered window), the data is not
            split at all, so that the result stays correct.
            """
            if get_window_kind(data) == "expanding":
                # An expanding window always starts at the beginning of the data.
                return nb_items, nb_workers

            window = getattr(data, "window", None)
            center = bool(getattr(data, "center", False))

            if isinstance(window, int) and not isinstance(window, bool) and not center:
                # One more item than needed is prepended, which is harmless, but
                # covers the `closed="both"` case.
                return window, nb_workers

            return 0, 1

        @staticmethod
        def get_nb_items(chunk: Tuple[int, Any], **kwargs) -> int:
            return chunk[1].shape[0]

        @staticmethod
        def get_work_extra(data: Any) -> Dict[str, Any]:
            return {
                "window_kind": get_window_kind(data),
                "attrs": get_window_attrs(data),
            }

        @staticmethod
        def work(
            data: Tuple[int, Any],
            user_defined_function: Callable,
            user_defined_function_args: tuple,
            user_defined_function_kwargs: Dict[str, Any],
            extra: Dict[str, Any],
        ) -> Any:
            nb_prepended, obj = data

            user_defined_function = wrap_user_defined_function_in_work(
                user_defined_function, obj.shape[0], extra
            )

            window = build_window(obj, extra["window_kind"], extra["attrs"])
            result = window.apply(
                user_defined_function,
                *user_defined_function_args,
                **user_defined_function_kwargs,
            )

            # The items which were only there to compute the first windows of this
            # chunk are removed: they belong to the previous chunk.
            return result.iloc[nb_prepended:] if nb_prepended else result

        @staticmethod
        def reduce(datas: Iterable[Any], extra: Dict[str, Any]) -> Any:
            datas = list(datas)

            if len(datas) == 1:
                return datas[0]

            return pd.concat(datas, copy=False)

